) VALUES (
    'val-gardena-venue-guide',
    '{"en": "Val Gardena: Classic Racing in the Dolomites", "de": "Gröden: Klassisches Racing in den Dolomiten", "fr": "Val Gardena : Courses classiques dans les Dolomites", "it": "Val Gardena: Gare classiche nelle Dolomiti", "es": "Val Gardena: Carreras clásicas en los Dolomitas", "pt": "Val Gardena: Corridas clássicas nas Dolomitas", "nl": "Val Gardena: Klassiek racen in de Dolomieten", "ar": "فال غاردينا: سباقات كلاسيكية في الدولوميت", "ja": "ヴァル・ガルデーナ：ドロミテでのクラシックレース", "zh": "Val Gardena: Duoluomite de Jingdian Bisai", "ko": "발 가르데나: 돌로미테에서의 클래식 레이싱"}'::jsonb,
    '{"en": "The Saslong course at Val Gardena is one of the most beautiful and technically demanding downhill tracks on the World Cup circuit. A true Italian classic.", "de": "Die Saslong-Strecke im Grödnertal ist eine der schönsten und technisch anspruchsvollsten Abfahrten im Weltcup-Zirkus.", "fr": "La piste Saslong de Val Gardena est l''une des descentes les plus belles et techniquement exigeantes du circuit de la Coupe du monde.", "it": "La pista Saslong in Val Gardena è una delle discese più belle e tecnicamente impegnative del circuito di Coppa del Mondo.", "es": "La pista Saslong de Val Gardena es una de las bajadas más hermosas y técnicamente exigentes del circuito de la Copa del Mundo.", "pt": "A pista Saslong de Val Gardena é uma das descidas mais bonitas e tecnicamente exigentes do circuito da Copa do Mundo.", "nl": "De Saslong piste in Val Gardena is een van de mooiste en technisch meest veeleisende afdalingen op het Wereldbeker circuit.", "ar": "يعد مسار ساسلونغ في فال غاردينا واحداً من أجمل وأصعب مسارات الانحدار من الناحية التقنية في دورة كأس العالم", "ja": "ヴァル・ガルデーナのサスロングコースは、ワールドカップサーキットで最も美しく技術的に要求の高いダウンヒルトラックの一つです。", "zh": "Val Gardena de Saslong saidao shi Shijie Bei saisaidao zhong zuimeili he jishu yaoqiu zuigao de huajiang saidao zhiyi.", "ko": "발 가르데나의 사슬롱 코스는 월드컵 서킷에서 가장 아름답고 기술적으로 까다로운 활강 트랙 중 하나입니다."}'::jsonb,
    '{"en": "<p>Val Gardena''s Saslong downhill is a jewel of Italian <a href=\"/alpine-skiing-guide/\">alpine skiing</a>. Set against the dramatic spires of the Dolomites, this course offers a unique combination of technical challenge and natural beauty.</p><h2>The Saslong</h2><p>The downhill course descends from the Ciampinoi plateau through a mix of technical sections and high-speed gliding passages. The famous Camel Humps create dramatic air time, while the Ciaslat meadows allow racers to carry incredible speed.</p><p>The course rewards skilled technicians who can maintain edge grip through varied terrain while building speed on the gliding sections.</p><h2>Dolomite Setting</h2><p>The Saslong race takes place with the Sella Group and Sassolungo peaks as a backdrop. The distinctive rock formations of the Dolomites, a UNESCO World Heritage site, create one of the most visually stunning settings in World Cup racing.</p><p>Champions like <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> and <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> have navigated this technical masterpiece.</p><h2>Race Weekend</h2><p>Val Gardena typically hosts both downhill and super-G, giving athletes two chances to tame this beautiful but demanding mountain. Combined with nearby <a href=\"/cortina-dampezzo-venue-guide/\">Cortina d''Ampezzo</a>, it forms a classic Italian racing stretch.</p><h2>Ladin Culture</h2><p>The region is home to the Ladin people, with their own language and cultural traditions. Visitors can experience this unique Alpine heritage in local villages and restaurants.</p><h2>Location</h2><p>Val Gardena is in the South Tyrol region of northern Italy, accessible from Bolzano or Innsbruck. The valley connects to the Sella Ronda ski circuit.</p><h2>Getting There</h2><p>The venue is about 40 km from Bolzano and accessible from Innsbruck Airport (about 100 km). Winter driving requires appropriate preparation.</p>", "de": "<p>Die Saslong-Abfahrt im Grödnertal ist ein Juwel des italienischen <a href=\"/alpine-skiing-guide/\">Ski Alpins</a>. Vor der dramatischen Kulisse der Dolomiten bietet diese Strecke eine einzigartige Kombination aus technischer Herausforderung und natürlicher Schönheit.</p><h2>Die Saslong</h2><p>Die Abfahrt führt vom Ciampinoi-Plateau durch eine Mischung aus technischen Abschnitten und Hochgeschwindigkeits-Gleitpassagen.</p><h2>Dolomiten-Kulisse</h2><p>Champions wie <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> und <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> haben dieses technische Meisterwerk bewältigt.</p><h2>Ladinische Kultur</h2><p>Die Region ist Heimat des ladinischen Volkes mit eigener Sprache und kulturellen Traditionen.</p>", "fr": "<p>La descente du Saslong à Val Gardena est un joyau du <a href=\"/alpine-skiing-guide/\">ski alpin</a> italien. Avec les flèches dramatiques des Dolomites en toile de fond, ce parcours offre une combinaison unique de défi technique et de beauté naturelle.</p><h2>Le Saslong</h2><p>La descente part du plateau de Ciampinoi à travers un mélange de sections techniques et de passages de glisse à haute vitesse.</p><h2>Décor des Dolomites</h2><p>Des champions comme <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> ont navigué ce chef-d''œuvre technique.</p>", "it": "<p>La discesa del Saslong in Val Gardena è un gioiello dello <a href=\"/alpine-skiing-guide/\">sci alpino</a> italiano. Ambientata contro le spettacolari guglie delle Dolomiti, questa pista offre una combinazione unica di sfida tecnica e bellezza naturale.</p><h2>Il Saslong</h2><p>La discesa scende dall''altopiano del Ciampinoi attraverso un mix di sezioni tecniche e passaggi di scorrimento ad alta velocità.</p><h2>Scenario dolomitico</h2><p>Campioni come <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> e <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> hanno affrontato questo capolavoro tecnico.</p><h2>Cultura ladina</h2><p>La regione è patria del popolo ladino, con propria lingua e tradizioni culturali.</p>", "es": "<p>El descenso del Saslong en Val Gardena es una joya del <a href=\"/alpine-skiing-guide/\">esquí alpino</a> italiano. Enmarcado contra las dramáticas agujas de los Dolomitas, este recorrido ofrece una combinación única de desafío técnico y belleza natural.</p><h2>El Saslong</h2><p>El descenso baja desde la meseta de Ciampinoi a través de una mezcla de secciones técnicas y pasajes de deslizamiento a alta velocidad.</p>", "pt": "<p>A descida do Saslong em Val Gardena é uma joia do <a href=\"/alpine-skiing-guide/\">esqui alpino</a> italiano. Situada contra os dramáticos pináculos das Dolomitas, esta pista oferece uma combinação única de desafio técnico e beleza natural.</p><h2>O Saslong</h2><p>A descida desce do planalto de Ciampinoi através de uma mistura de seções técnicas e passagens de deslizamento em alta velocidade.</p>", "nl": "<p>De Saslong afdaling in Val Gardena is een juweel van het Italiaanse <a href=\"/alpine-skiing-guide/\">alpine skiën</a>. Tegen de dramatische torenspitsen van de Dolomieten biedt dit parcours een unieke combinatie van technische uitdaging en natuurlijke schoonheid.</p><h2>De Saslong</h2><p>De afdaling daalt af van het Ciampinoi plateau door een mix van technische secties en hoge snelheid glijpassages.</p>", "ar": "<p>انحدار ساسلونغ في فال غاردينا هو جوهرة <a href=\"/alpine-skiing-guide/\">التزلج الألبي</a> الإيطالي. مع القمم الدراماتيكية للدولوميت كخلفية، يقدم هذا المسار مزيجاً فريداً من التحدي التقني والجمال الطبيعي.</p><h2>ساسلونغ</h2><p>ينحدر المسار من هضبة شيامبينوي عبر مزيج من الأقسام التقنية وممرات الانزلاق عالية السرعة.</p>", "ja": "<p>ヴァル・ガルデーナのサスロングダウンヒルは、イタリアの<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>の宝石です。ドロミテの劇的な尖塔を背景に、このコースは技術的なチャレンジと自然の美しさのユニークな組み合わせを提供します。</p><h2>サスロング</h2><p>ダウンヒルコースは、チャンピノイ高原から技術セクションと高速グライディングパッセージのミックスを通って下ります。</p>", "zh": "<p>Val Gardena de Saslong huajiang shi Yidali <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> de zhenzhu. Yi Duoluomite de xijuhua jianlou wei beijing, zhe tiao saidao tigong le jishu tiaozhan he ziran meili de dute jiehe.</p><h2>Saslong</h2><p>Huajiang saidao cong Ciampinoi gaoyuan xia jiang, chuanguo jishu luduan he gaosu huaxing tongdao de hunhe.</p>", "ko": "<p>발 가르데나의 사슬롱 활강은 이탈리아 <a href=\"/alpine-skiing-guide/\">알파인 스키</a>의 보석입니다. 돌로미테의 극적인 첨탑을 배경으로 이 코스는 기술적 도전과 자연미의 독특한 조합을 제공합니다.</p><h2>사슬롱</h2><p>활강 코스는 참피노이 고원에서 기술 구간과 고속 글라이딩 통로의 혼합을 통해 내려갑니다.</p>"}'::jsonb,
    'venue-guide',
    'AS',
    '{"en": "Val Gardena venue guide - Home of the Saslong downhill in the Italian Dolomites, combining technical racing with stunning UNESCO World Heritage mountain scenery.", "de": "Gröden Venue Guide - Heimat der Saslong-Abfahrt in den italienischen Dolomiten.", "fr": "Guide du site de Val Gardena - Terre de la descente du Saslong dans les Dolomites italiennes.", "it": "Guida alla sede di Val Gardena - Casa della discesa del Saslong nelle Dolomiti italiane.", "es": "Guía del lugar de Val Gardena - Hogar del descenso del Saslong en los Dolomitas italianos.", "pt": "Guia do local de Val Gardena - Lar da descida do Saslong nas Dolomitas italianas.", "nl": "Val Gardena locatiegids - Thuisbasis van de Saslong afdaling in de Italiaanse Dolomieten.", "ar": "دليل موقع فال غاردينا - موطن انحدار ساسلونغ في الدولوميت الإيطالية", "ja": "ヴァル・ガルデーナ会場ガイド - イタリアのドロミテにあるサスロングダウンヒルの本拠地", "zh": "Val Gardena changguan zhinan - Yidali Duoluomite Saslong huajiang de jiayuan", "ko": "발 가르데나 경기장 가이드 - 이탈리아 돌로미테의 사슬롱 활강의 본거지"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
